func (this *Control) CheckGesture() {
	var value int32 = this.impl.getSystemMetrics_(win32.OSSM_DIGITIZER)
	if (value & (win32.OSNID_READY | win32.OSNID_MULTI_INPUT)) != 0 {
		var config *win32.GESTURECONFIG = win32.NewGESTURECONFIG()
		config.DwID = win32.OSGID_ROTATE
		config.DwWant = 1
		config.DwBlock = 0
		win32.OSSetGestureConfig(this.Handle, 0, 1, config, win32.GESTURECONFIGSizeof)
	}
}

func (this *Control) CheckMirrored() {
	if (this.style & RIGHT_TO_LEFT) != 0 {
		var bits int32 = win32.OSGetWindowLong(this.Handle, win32.OSGWL_EXSTYLE)
		if (bits & win32.OSWS_EX_LAYOUTRTL) != 0 {
			this.style |= MIRRORED
		}
	}
}

